#include "DesignationRuntime.hpp"
namespace elysium::fortress {bool DesignationRuntime::add(Designation d,std::string&w){if(!d.id||d.target.x1<d.target.x0||d.target.y1<d.target.y0||d.target.z1<d.target.z0){w="invalid designation";return false;}if(!rows_.emplace(d.id,std::move(d)).second){w="duplicate designation";return false;}return true;}std::optional<JobRequest>DesignationRuntime::compile(StableId id,std::uint64_t rev,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown designation";return std::nullopt;}auto&d=i->second;if(d.status==DesignationStatus::Cancelled||d.status==DesignationStatus::Completed){w="inactive designation";return std::nullopt;}if(d.worldRevision!=rev){d.status=DesignationStatus::Blocked;w="world changed";return std::nullopt;}d.status=DesignationStatus::Compiled;return JobRequest{d.id,d.owner,d.type,d.target,d.priority};}bool DesignationRuntime::cancel(StableId id){auto i=rows_.find(id);if(i==rows_.end())return false;i->second.status=DesignationStatus::Cancelled;return true;}}
